using System.Threading.Tasks;
using Octoshift.Models;

namespace OctoshiftCLI.Services;

/// <summary>
/// Orchestrates a safe test of an Azure DevOps pipeline migration to GitHub. The pipeline is
/// temporarily rewired to GitHub, a build is queued, the pipeline is immediately restored to its
/// original Azure DevOps repository, and the resulting build is monitored for its outcome.
/// </summary>
public class PipelineTestService
{
    private readonly OctoLogger _log;
    private readonly AdoApi _adoApi;
    private readonly AdoPipelineTriggerService _pipelineTriggerService;

    private const int DefaultMonitorTimeoutMinutes = 30;
    private const int PollIntervalSeconds = 5;

    public PipelineTestService(OctoLogger log, AdoApi adoApi, AdoPipelineTriggerService pipelineTriggerService)
    {
        _log = log;
        _adoApi = adoApi;
        _pipelineTriggerService = pipelineTriggerService;
    }

    public virtual async Task<PipelineTestResult> TestPipeline(PipelineTestArgs args)
    {
        if (args is null)
        {
            throw new ArgumentNullException(nameof(args));
        }

        var result = new PipelineTestResult
        {
            AdoOrg = args.AdoOrg,
            AdoTeamProject = args.AdoTeamProject,
            PipelineName = args.AdoPipeline,
            StartTime = DateTime.UtcNow,
        };

        // Resolve the pipeline ID, looking it up by name when it was not supplied.
        var pipelineId = args.PipelineId ?? await _adoApi.GetPipelineId(args.AdoOrg, args.AdoTeamProject, args.AdoPipeline);
        result.PipelineId = pipelineId;

        // Retrieve the original pipeline configuration so it can be restored afterwards.
        var (defaultBranch, clean, checkoutSubmodules, triggers) = await _adoApi.GetPipeline(args.AdoOrg, args.AdoTeamProject, pipelineId);
        result.AdoRepoName = await _adoApi.GetPipelineRepositoryName(args.AdoOrg, args.AdoTeamProject, pipelineId);

        if (args.DryRun)
        {
            _log.LogInformation("Running in dry-run mode. The pipeline would be rewired to GitHub, a build queued, and then restored to Azure DevOps.");
            result.EndTime = DateTime.UtcNow;
            return result;
        }

        // Rewire the pipeline to GitHub.
        _log.LogInformation("Rewiring pipeline to GitHub...");
        await _pipelineTriggerService.RewirePipelineToGitHub(
            args.AdoOrg,
            args.AdoTeamProject,
            pipelineId,
            defaultBranch,
            clean,
            checkoutSubmodules,
            args.GithubOrg,
            args.GithubRepo,
            args.ServiceConnectionId,
            triggers,
            args.TargetApiUrl);
        result.RewiredSuccessfully = true;

        // Queue a build against the rewired pipeline.
        _log.LogInformation("Queueing test build...");
        var buildId = await _adoApi.QueueBuild(args.AdoOrg, args.AdoTeamProject, pipelineId);
        result.BuildId = buildId;

        // Restore the pipeline to its original Azure DevOps repository immediately after queueing.
        try
        {
            _log.LogInformation("Restoring pipeline to Azure DevOps repo...");
            await _pipelineTriggerService.RestorePipelineToAdoRepo(
                args.AdoOrg,
                args.AdoTeamProject,
                pipelineId,
                defaultBranch,
                clean,
                checkoutSubmodules,
                result.AdoRepoName,
                triggers);
            result.RestoredSuccessfully = true;
        }
        catch (Exception ex)
        {
            result.RestoredSuccessfully = false;
            result.ErrorMessage = $"Failed to restore: {ex.Message}";
            result.EndTime = DateTime.UtcNow;
            return result;
        }

        // Monitor the queued build until it completes or the timeout elapses.
        await MonitorBuild(args, result, buildId);

        return result;
    }

    private async Task MonitorBuild(PipelineTestArgs args, PipelineTestResult result, int buildId)
    {
        var timeoutMinutes = args.MonitorTimeoutMinutes > 0 ? args.MonitorTimeoutMinutes : DefaultMonitorTimeoutMinutes;
        var deadline = DateTime.UtcNow.AddMinutes(timeoutMinutes);

        while (true)
        {
            var (status, buildResult, buildUrl) = await _adoApi.GetBuild(args.AdoOrg, args.AdoTeamProject, buildId);

            result.Status = status;
            result.Result = buildResult;
            result.BuildUrl = buildUrl;

            if (result.IsCompleted)
            {
                result.EndTime = DateTime.UtcNow;
                break;
            }

            if (DateTime.UtcNow >= deadline)
            {
                result.EndTime = DateTime.UtcNow;
                result.ErrorMessage = $"Timed out after {timeoutMinutes} minutes waiting for the build to complete.";
                break;
            }

            await Task.Delay(TimeSpan.FromSeconds(PollIntervalSeconds));
        }
    }
}
